+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+"
+                    + "@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?"
+                    + "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*"
+                    + "\\.[A-Za-z]{2,}$");
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>();
+
+    private final MessageStore store = MessageStore.get();
+
+    public ContactView() {
+        setPadding(true);
+        setSpacing(true);
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        message.setHeight("8em");
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+        form.setMaxWidth("40em");
+
+        for (TextFieldBase<?, String> field : fields()) {
+            // The form does its own validating when Send is pressed; the fields
+            // must not overrule that on their own.
+            field.setManualValidation(true);
+            // Send has to react to typing, not only to leaving a field.
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(event -> send.setEnabled(true));
+        }
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        add(form, send);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name")
+                .setAutoWidth(true);
+        messages.addColumn(ContactMessage::message).setHeader("Message")
+                .setAutoWidth(true);
+        messages.addColumn(ContactMessage::email).setHeader("Email")
+                .setAutoWidth(true);
+        messages.addColumn(ContactMessage::phone).setHeader("Phone")
+                .setAutoWidth(true);
+        messages.setAllRowsVisible(true);
+        add(messages);
+
+        refreshMessages();
+    }
+
+    private List<TextFieldBase<?, String>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private void trySend() {
+        if (!validate()) {
+            // Nothing is sent, and what was typed stays put.
+            return;
+        }
+        store.add(new ContactMessage(name.getValue().strip(),
+                email.getValue().strip(), phone.getValue().strip(),
+                message.getValue()));
+        refreshMessages();
+        Notification.show("Message sent");
+        clearForm();
+        // Enabled again as soon as the user edits any field.
+        send.setEnabled(false);
+    }
+
+    /**
+     * Marks every field that breaks a rule invalid and returns whether the form
+     * as a whole is valid.
+     */
+    private boolean validate() {
+        clearErrors();
+
+        String enteredName = name.getValue().strip();
+        String enteredEmail = email.getValue().strip();
+        String enteredPhone = phone.getValue().strip();
+        String enteredMessage = message.getValue();
+
+        boolean valid = true;
+
+        if (enteredName.isEmpty()) {
+            markInvalid(name, NAME_REQUIRED);
+            valid = false;
+        }
+
+        if (!enteredEmail.isEmpty()
+                && !EMAIL_PATTERN.matcher(enteredEmail).matches()) {
+            markInvalid(email, EMAIL_INVALID);
+            valid = false;
+        } else if (enteredEmail.isEmpty() && enteredPhone.isEmpty()) {
+            markInvalid(email, CONTACT_REQUIRED);
+            valid = false;
+        }
+
+        if (enteredMessage.strip().isEmpty()) {
+            markInvalid(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (enteredMessage.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+
+        return valid;
+    }
