+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+
+        dialog.open();
+    }
+}
